// Expand each search into one row per patent, and flatten the fields that
// arrive as arrays so a spreadsheet cell can hold them.
const weekOf = $now.toFormat('yyyy-MM-dd');

const list = (v) => (Array.isArray(v) ? v.filter(Boolean).join(', ') : String(v || ''));
const clip = (s, n) => {
  const v = String(s || '').replace(/\s+/g, ' ').trim();
  return v.length > n ? v.slice(0, n - 3) + '...' : v;
};

const rows = [];
for (const item of $input.all()) {
  const term = (item.json.search_parameters || {}).q || '';
  for (const p of item.json.patents || []) {
    rows.push({
      json: {
        'Week of': weekOf,
        'Watch term': term,
        Title: clip(p.title, 200),
        Assignee: list(p.assignee),
        Inventor: list(p.inventor),
        'Publication number': p.publication_number || '',
        'Publication date': p.publication_date || '',
        'Filing date': p.filing_date || '',
        Summary: clip(p.snippet, 500),
        'Patent link': p.patent_link || '',
      },
    });
  }
}
return rows;
